//! Native contract + graph DSL — the custom Starlark value types.
//!
//! The frozen custom Starlark values returned by the contract/graph builtins
//! (see [`super::contract_globals`] and [`super::graph_globals`]).
//!
//! # `unsafe`
//!
//! starlark's `#[derive(ProvidesStaticType)]` expands to an `unsafe impl`, so
//! this module opts out of the crate-level `deny(unsafe_code)`. No hand-written
//! `unsafe` appears here; the only `unsafe` is generated by the derive macro and
//! is sound by construction (the types carry no lifetimes).
#![allow(unsafe_code)]
// The `#[starlark_value]` attribute macro requires the `impl<'v>
// StarlarkValue<'v>` blocks to spell `'v` explicitly (eliding to `'_` breaks its
// expansion), which trips `clippy::elidable_lifetime_names`.
#![allow(clippy::elidable_lifetime_names)]

use allocative::Allocative;
use derive_more::Display;
use serde_json::Value as JsonValue;
use starlark::starlark_simple_value;
use starlark::values::{NoSerialize, ProvidesStaticType, StarlarkValue, starlark_value};

use super::schema::{ContractShape, DslType, Primitive, PrimitiveConstraints};

// ── Custom value types ──────────────────────────────────────────────────────

/// A named object contract: an ordered set of typed [`Field`]s plus the
/// generated JSON schema.
///
/// Returned by the `contract(name, {..})` builtin and consumed by `field`
/// when nested. The cached `schema` is the constrained JSON-Schema object the
/// agent-run validator accepts.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("contract({})", shape.name)]
pub(crate) struct Contract {
    #[allocative(skip)]
    pub(crate) shape: ContractShape,
    #[allocative(skip)]
    pub(crate) schema: JsonValue,
}

starlark_simple_value!(Contract);

#[starlark_value(type = "kata.contract")]
impl<'v> StarlarkValue<'v> for Contract {}

/// A single contract field: a declared type plus required/doc metadata.
///
/// Returned by `field(ty, required=.., doc=..)` and only meaningful as a value
/// of the `fields` dict passed to `contract`.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("field")]
pub(crate) struct Field {
    #[allocative(skip)]
    pub(crate) ty: DslType,
    /// `field(required=..)` — `None` when the author did not spell it, so it
    /// carries the DEFAULT (`True`).
    ///
    /// This is an `Option<bool>` rather than a `bool` so the two cases stay
    /// distinguishable. `field()`'s documented rules turn on an EXPLICIT
    /// `required=`: `default=` plus an explicit `required=True` is a
    /// contradiction and `secret=True` plus an explicit `required=False` is a
    /// contradiction, while `field(ty, default=..)` — the ordinary spelling,
    /// which carries `required` only by default — is the intended way to
    /// declare an optional param. Collapsed to a plain `bool`, those are the
    /// same value and neither rejection can be written at all.
    pub(crate) required: Option<bool>,
    pub(crate) doc: Option<String>,
    /// `field(default=..)` — the author-declared default VALUE for a
    /// `workflow(params=..)` param (as JSON). `None` for a `contract(..)` field
    /// (defaults are param-only; `contract()` rejects a field that sets one).
    #[allocative(skip)]
    pub(crate) default: Option<serde_json::Value>,
    /// `field(secret=..)` — marks a `workflow(params=..)` param secret
    /// (never carried by operator projections). `false` for a `contract(..)` field.
    pub(crate) secret: bool,
}

starlark_simple_value!(Field);

#[starlark_value(type = "kata.field")]
impl<'v> StarlarkValue<'v> for Field {}

