/// A constrained primitive marker returned by `number(..)`, `integer(..)`, or
/// `string(..)`: a primitive leaf plus its author-declared VALUE CONSTRAINTS.
/// Accepted anywhere a primitive-spelling string is (as a `field(..)`
/// type, a `list_of(..)` element, or a `variant(..)` arm); the constraints are
/// carried into the field's [`DslType`] and lowered onto the JSON node.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("{}", primitive.schema_type())]
pub(crate) struct PrimitiveType {
    #[allocative(skip)]
    pub(crate) primitive: Primitive,
    #[allocative(skip)]
    pub(crate) constraints: PrimitiveConstraints,
}

starlark_simple_value!(PrimitiveType);

#[starlark_value(type = "kata.primitive")]
impl<'v> StarlarkValue<'v> for PrimitiveType {}

/// A lightweight handle to a registered stage, returned by `stage(..)`.
///
/// Carries only the stage's stable id; the full node lives in the thread-local
