/// and `workflow(root=..)` to wire the graph without re-stating prompts.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("stage({id})")]
pub(crate) struct StageRef {
    pub(crate) id: String,
}

starlark_simple_value!(StageRef);

#[starlark_value(type = "kata.stage")]
impl<'v> StarlarkValue<'v> for StageRef {}

