/// A stage topology declaration (`topology(..)`).
///
/// Carries the normalized JSON shape for
/// [`kata_types::workflow::StageTopology`]. Lowering routes this JSON through
/// the shared `starlark_eval::topology_from_json` typed decoder.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("topology({kind})", kind = self.kind())]
pub(crate) struct Topology {
    #[allocative(skip)]
    pub(crate) json: JsonValue,
}

impl Topology {
    fn kind(&self) -> &str {
        self.json
            .get("kind")
            .and_then(JsonValue::as_str)
            .unwrap_or("?")
    }
}

starlark_simple_value!(Topology);

#[starlark_value(type = "kata.topology")]
impl<'v> StarlarkValue<'v> for Topology {}

