/// A composable walk-away bound (`time_bound(..)` / `cost_bound(..)` /
/// `token_bound(..)`).
///
/// Carries the typed, already-value-validated [`kata_types::bound::Bound`] the
/// `workflow(bounds=[..])` drain lowers onto
/// [`kata_types::workflow::WorkflowDefinition::bounds`].
///
/// The runner consumes the lowered value as a durable workflow/loop walk-away:
/// cost and tokens use accumulated usage and time uses the appropriate
/// original-start or per-loop anchor.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("bound")]
pub(crate) struct BoundValue {
    #[allocative(skip)]
    pub(crate) bound: kata_types::bound::Bound,
}

starlark_simple_value!(BoundValue);

#[starlark_value(type = "kata.bound")]
impl<'v> StarlarkValue<'v> for BoundValue {}

// `sleep(..)` has no frozen-value handle of its own: it is a graph NODE
// (registering a stage and returning a [`StageRef`], exactly like `stage()` /
// `subworkflow()`). The resolved wake target travels as
// [`kata_types::workflow::DurableSleepSpec`] on the stage and lowers to
// [`kata_types::wait::DurableSleep`] in the checked IR.

/// A durable engine schedule (`schedule(id=..,submit=..,every_ms=..|cron=..)`).
///
/// Carries the validated [`crate::schedule::ScheduleSpec`] the
/// `kata_workflow::schedule::ScheduleEngine` installs into its durable store and
/// submits when due. The `cron`/interval trigger is parsed + validated at
/// authoring time inside the `schedule()` builtin, so a malformed expression is
/// a load-time (fail-closed) error.
#[derive(Clone, Debug, Display, ProvidesStaticType, NoSerialize, Allocative)]
#[display("schedule({})", spec.id)]
pub(crate) struct ScheduleValue {
    #[allocative(skip)]
    pub(crate) spec: crate::schedule::ScheduleSpec,
}

starlark_simple_value!(ScheduleValue);

#[starlark_value(type = "kata.schedule")]
impl<'v> StarlarkValue<'v> for ScheduleValue {}
